<?php require_once __DIR__.'/../config/bootstrap.php'; if(current_user()) redirect('aluno/area.php'); $err=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf(); $nome=trim($_POST['nome']??'');$email=strtolower(trim($_POST['email']??''));$nasc=$_POST['data_nascimento']??null;$senha=$_POST['senha']??'';$confirm=$_POST['confirmar']??''; if(mb_strlen($nome)<3||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($senha)<8||$senha!==$confirm)$err='Preencha os dados corretamente. A senha deve ter pelo menos 8 caracteres e as senhas devem coincidir.'; else {try{$s=db()->prepare('INSERT INTO users(nome,email,senha,data_nascimento) VALUES(?,?,?,?)');$s->execute([$nome,$email,password_hash($senha,PASSWORD_DEFAULT),$nasc?:null]);$newUserId=(int)db()->lastInsertId(); notify_admin_new_student($newUserId); login_user($newUserId); flash('success','Cadastro realizado com sucesso.'); redirect('aluno/area.php');}catch(PDOException $e){$err=str_contains($e->getMessage(),'Duplicate')?'Este e-mail já está cadastrado.':'Não foi possível realizar o cadastro.';}}} ?>
<?php layout_header('Criar conta'); ?><div class="auth-card"><a class="auth-back" href="<?=e(url())?>">← Voltar</a><img class="auth-logo theme-logo theme-logo-dark" src="<?=e(url('assets/img/heal-logo.png'))?>"><img class="auth-logo theme-logo theme-logo-light" src="<?=e(url('assets/img/heal-logo-light.png'))?>"><h1>Criar sua conta</h1><p class="subtitle">Cadastre-se para acessar cursos, progresso e certificados.</p><?php if($err): ?><div class="form-error"><?=e($err)?></div><?php endif; ?><form method="post"><?=csrf_field()?><label>Nome completo</label><input name="nome" required><label>Data de nascimento</label><input type="date" name="data_nascimento"><label>E-mail</label><input type="email" name="email" required><label>Senha</label><input type="password" name="senha" minlength="8" required><label>Confirmar senha</label><input type="password" name="confirmar" minlength="8" required><button class="btn" type="submit">Criar minha conta</button></form><p class="login-hint">Já possui cadastro? <a href="<?=e(url('aluno/login.php'))?>">Entrar</a></p></div><?php layout_footer(); ?>
